//! 启动参数: 命令行里传进来的单个目录, 尝试作为 WebGAL 项目打开。
//!
//! 场景是"从文件管理器 / 终端 / 其它工具把项目目录丢给 Ink":
//! `webgal-ink D:\games\my-story`。参数只在这里解析一次, 前端启动时取一次结果。
//!
//! 口径刻意保守 —— **只有像 WebGAL 项目的目录才认**:
//! * 必须是目录, 且已经存在;
//! * 里面要有 `game/config.txt` 或 `game/` 目录。
//!
//! 不满足就返回 `None`, 应用照常进开始界面。宁可什么都不做, 也不要因为参数里混进了
//! 一个无关路径就打开一个"项目" —— 那样界面会缺场景、缺配置, 用户只会以为是程序坏了。
//!
//! 参数只认**位置参数**: 以 `-` 开头的当成选项跳过。真正的过滤靠上面那条目录判据,
//! 所以 `tauri dev` 之类工具往 argv 里塞的东西不会误伤。

use std::path::{Path, PathBuf};

/// 判定一个目录是不是 WebGAL 项目: 有 `game/config.txt`, 或者至少有 `game/` 目录。
///
/// 用"或"而不是只看 `config.txt`: 有些老项目把配置写成了别的形式, 但仍然是一个能打开的
/// 项目目录; 而只有 `game/` 一条时编辑器也能正常列出场景与资源。
fn looks_like_webgal_project(dir: &Path) -> bool {
    if !dir.is_dir() {
        return false;
    }
    let game = dir.join("game");
    game.join("config.txt").is_file() || game.is_dir()
}

/// 从一串参数里挑出要打开的项目目录 (纯函数, 便于单测)。
///
/// 传进来的应当是 `std::env::args()` 的**完整**序列 —— 内部会跳过第 0 个 (程序自身路径)。
/// 只取第一个命中的: 打开两个目录没有语义。
fn project_from_args<I: IntoIterator<Item = String>>(args: I) -> Option<PathBuf> {
    args.into_iter()
        .skip(1)
        .filter(|arg| !arg.starts_with('-'))
        .map(PathBuf::from)
        .find(|candidate| looks_like_webgal_project(candidate))
}

/// 命令行指定的项目目录 (没有则为 `None`)。
///
/// 返回**绝对路径**: 启动时的当前目录与之后的"最近项目"记录属于两回事, 存相对路径会在下次
/// 打开时对不上。
///
/// 用 `std::path::absolute` 而**不是** `canonicalize`: 后者在 Windows 上会返回带 `\\?\` 前缀的
/// verbatim 路径, 前端拿它拼 URL / 预览站点 / 传给语言服务都会出问题。前者只做"补上当前目录",
/// 不解析符号链接也不加前缀。
#[tauri::command]
pub fn startup_project_path() -> Option<String> {
    let found = project_from_args(std::env::args())?;
    let absolute = std::path::absolute(&found).unwrap_or(found);
    Some(absolute.to_string_lossy().into_owned())
}

#[cfg(test)]
mod tests {
    use super::project_from_args;
    use std::{
        fs,
        path::PathBuf,
        time::{SystemTime, UNIX_EPOCH},
    };

    fn temp_dir(tag: &str) -> PathBuf {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock should be after UNIX epoch")
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("webgal-ink-startup-{tag}-{unique}"));
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn args(values: &[&str]) -> Vec<String> {
        values.iter().map(|value| value.to_string()).collect()
    }

    #[test]
    fn accepts_a_directory_holding_game_config() {
        let root = temp_dir("config");
        fs::create_dir_all(root.join("game")).unwrap();
        fs::write(root.join("game").join("config.txt"), "Game_name:demo;\n").unwrap();

        let path = root.to_string_lossy().into_owned();
        let found = project_from_args(args(&["webgal-ink.exe", &path]));
        assert_eq!(found, Some(root.clone()));

        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn accepts_a_directory_holding_only_the_game_folder() {
        let root = temp_dir("game-only");
        fs::create_dir_all(root.join("game").join("scene")).unwrap();

        let found = project_from_args(args(&["webgal-ink.exe", root.to_str().unwrap()]));
        assert_eq!(found, Some(root.clone()));

        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn ignores_directories_that_are_not_projects() {
        let root = temp_dir("plain");
        let found = project_from_args(args(&["webgal-ink.exe", root.to_str().unwrap()]));
        assert_eq!(found, None);

        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn ignores_options_and_the_binary_path() {
        let root = temp_dir("flag");
        fs::create_dir_all(root.join("game")).unwrap();
        let path = root.to_string_lossy().into_owned();
        // 二进制路径本身永远不当作项目 (即使它所在的目录恰好像个项目也不行)
        let found = project_from_args(args(&[&path, "--config", &path]));
        assert_eq!(found, Some(root.clone()));

        // 只有选项与小参数时没有任何结果
        assert_eq!(project_from_args(args(&["webgal-ink.exe", "--help"])), None);

        fs::remove_dir_all(root).unwrap();
    }
}
